<?php require_once __DIR__.'/../includes/header.php';checkAuth(['economia','admin']);$db=getDBConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$db->prepare('INSERT INTO banco_movimientos(cuenta_id,tipo,concepto,monto_cup,referencia,fecha,usuario_id) VALUES(?,?,?,?,?,?,?)');$tipo=$_POST['tipo'];$monto=(float)$_POST['monto'];$s->execute([(int)$_POST['cuenta_id'],$tipo,trim($_POST['concepto']),$monto,trim($_POST['referencia']),now(),$_SESSION['usuario']['id']]);$delta=$tipo==='entrada'?$monto:-$monto;$db->prepare('UPDATE banco_cuentas SET saldo_cup=saldo_cup+? WHERE id=?')->execute([$delta,(int)$_POST['cuenta_id']]);$msg='Movimiento bancario registrado.';}$accounts=$db->query('SELECT * FROM banco_cuentas WHERE activa=1 ORDER BY nombre')->fetchAll();$moves=$db->query('SELECT m.*,b.nombre cuenta FROM banco_movimientos m JOIN banco_cuentas b ON b.id=m.cuenta_id ORDER BY m.id DESC LIMIT 40')->fetchAll();?><div class="grid grid-2"><div class="card"><h1>Cuenta bancaria</h1><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><form method="post"><label>Cuenta</label><select name="cuenta_id"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['nombre'])?> · <?=money($a['saldo_cup'])?></option><?php endforeach;?></select><label>Tipo</label><select name="tipo"><option value="entrada">Entrada</option><option value="salida">Salida</option></select><label>Monto CUP</label><input type="number" step="0.01" name="monto" required><label>Concepto</label><input name="concepto" required><label>Referencia</label><input name="referencia"><button class="btn gold" style="margin-top:12px">Registrar</button></form></div><div class="card"><h2>Movimientos</h2><div class="table-wrap"><table><tr><th>Fecha</th><th>Cuenta</th><th>Tipo</th><th>Monto</th><th>Concepto</th></tr><?php foreach($moves as $m):?><tr><td><?=h($m['fecha'])?></td><td><?=h($m['cuenta'])?></td><td><?=strtoupper($m['tipo'])?></td><td class="gold"><?=money($m['monto_cup'])?></td><td><?=h($m['concepto'])?></td></tr><?php endforeach;?></table></div></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
